// Polish curated batch, split out of `suppliers_data.ts` for the same reason
// the Croatian one is: neither file may cross Biome's 1 MiB ceiling, past which
// the formatter and the linter skip it entirely and nothing written into it is
// checked again. Nothing else about these entries is different: `RAW_DIRECTORY`
// spreads this const alongside the others and every downstream read is
// unchanged.
//
// The type import is `import type` on purpose. `suppliers_data.ts` imports this
// const as a value, so a value import back the other way would be a runtime
// cycle; a type-only import is erased at compile time and is not.

import type { RawDirectoryEntry } from "./suppliers_data";

// The same resting shape the entries in `suppliers_data.ts` spread. Kept local
// rather than imported, for the reason above.
const noContact = {
  contact_email: null,
  contact_phone: null,
  lat: null,
  lng: null,
} as const;

// ── Poland, August 2026 ───────────────────────────────────────────────────
// 200 researched wedding venues, 12–13 per voivodeship so no region is a blank
// on the map. Country resolves from the `, PL` city suffix (`curatedCountry`),
// which also makes PL the language of the claim-invite mail via
// `localeForCountry`, and since Weddly ships no Polish UI that resolves to
// the English card rather than to a Hungarian one.
//
// Four things about this batch are worth knowing before editing it:
//
//   • `blurb_hu` is POLISH here, not Hungarian. The column name is historic;
//     `shared/listing_language.ts` is the one place that answers "local to
//     what?", and for PL it answers Polish. Both descriptions are built from
//     the same researched facts (type, town, capacity, halls, facilities,
//     kitchen, beds), so neither says anything the other does not.
//
//   • `price_band` is set ONLY where a published price was found. The source
//     research also carried an estimated band for the venues that publish
//     nothing, derived from their type and positioning, and its own methodology
//     note says that figure is directional and must be confirmed with the venue
//     before publication. A guess rendered as a `$$$` on a card is not a guess
//     any more, so those entries ship with no band at all.
//
//   • `contact_phone` is null throughout. The research recorded numbers as
//     "visible after click on source page" rather than digits, and a partial
//     number is not a phone number.
//
//   • `contact_email_flag: "unverified"` marks an address that does not sit on
//     the venue's own domain and does not carry its name or town: a holding
//     company, a hotel group's sales desk, a staff member's private mailbox.
//     Stored and visible to an admin, held back from the claim-invite campaign
//     and from every couple-facing exit until somebody checks it.
//
// `gallery_urls` hotlink each venue's own website and are re-hosted CSP-safe by
// the boot gallery/hero sweeps. 154 of the 200 resolved a photo that clears the
// hero quality gate; the rest are JS-rendered sites an HTML read cannot see
// into, and their cards draw the category placeholder until the boot sweep or a
// claiming vendor supplies one.
